/**
 * Dashboard Date Utilities
 *
 * Handles date range computation, validation, and formatting
 *
 * @package ContactInbox\Dashboard\JS
 */

const DashboardDateUtils = {
    /**
     * Check if a value is a date-based preset (not rolling days)
     */
    isDateBasedPreset(value) {
        return [
            'today',
            'yesterday',
            'this_week',
            'this_month',
            'last_month',
            'last_3_months',
            'last_6_months',
        ].includes(value);
    },

    /**
     * Compute preset dates based on selection
     */
    computePresetDates(value) {
        const today = new Date();
        const formatDate = (d) => d.toISOString().slice(0, 10);

        const startOfMonth = (d) => new Date(d.getFullYear(), d.getMonth(), 1);
        const endOfMonth = (d) => new Date(d.getFullYear(), d.getMonth() + 1, 0);

        const getQuarter = (d) => Math.floor(d.getMonth() / 3) + 1;
        const startOfQuarter = (year, quarter) => new Date(year, (quarter - 1) * 3, 1);
        const endOfQuarter = (year, quarter) => new Date(year, quarter * 3, 0);

        const startOfWeek = (d) => {
            const day = d.getDay(); // 0=Sun
            const offset = (day + 6) % 7; // Monday-start
            const s = new Date(d);
            s.setDate(s.getDate() - offset);
            return s;
        };

        switch (value) {
            case 'today': {
                const day = formatDate(today);
                return { start: day, end: day };
            }
            case 'yesterday': {
                const y = new Date(today);
                y.setDate(y.getDate() - 1);
                const day = formatDate(y);
                return { start: day, end: day };
            }
            case 'this_week': {
                const start = formatDate(startOfWeek(today));
                const end = formatDate(today);
                return { start, end };
            }
            case 'this_month': {
                const start = formatDate(startOfMonth(today));
                const end = formatDate(today);
                return { start, end };
            }
            case 'last_month': {
                const lastMonthDate = new Date(today.getFullYear(), today.getMonth() - 1, 1);
                const start = formatDate(startOfMonth(lastMonthDate));
                const end = formatDate(endOfMonth(lastMonthDate));
                return { start, end };
            }
            case 'last_3_months': {
                const startDate = new Date(today);
                startDate.setMonth(startDate.getMonth() - 3);
                const start = formatDate(startDate);
                const end = formatDate(today);
                return { start, end };
            }
            case 'last_6_months': {
                const startDate = new Date(today);
                startDate.setMonth(startDate.getMonth() - 6);
                const start = formatDate(startDate);
                const end = formatDate(today);
                return { start, end };
            }
            default:
                return null;
        }
    },

    /**
     * Format a date string for display
     */
    formatDateLabel(dateStr) {
        const date = new Date(dateStr);
        if (isNaN(date.getTime())) return dateStr;
        const options = { month: 'short', day: 'numeric', year: 'numeric' };
        return date.toLocaleDateString(undefined, options);
    },

    /**
     * Format duration in milliseconds
     */
    formatDuration(ms) {
        if (ms === null || typeof ms === 'undefined') return '—';
        const num = parseFloat(ms);
        if (Number.isNaN(num)) return '—';

        if (num < 1000) {
            return `${Math.round(num)} ms`;
        }
        if (num < 60000) {
            return `${(num / 1000).toFixed(1)} s`;
        }
        if (num < 3600000) {
            return `${(num / 60000).toFixed(1)} min`;
        }
        return `${(num / 3600000).toFixed(1)} hr`;
    },

    /**
     * Format a date string for display (with time)
     * Handles MySQL datetime format: YYYY-MM-DD HH:MM:SS
     * Note: WordPress times are already in WordPress timezone via current_time('mysql', true)
     */
    formatDate(dateString) {
        if (!dateString || dateString === '—') return '—';
        
        try {
            // WordPress sends datetime as YYYY-MM-DD HH:MM:SS in WordPress timezone
            // Just validate and return it as-is for display
            if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(dateString)) {
                return dateString;
            }
            
            // Fallback: try to parse and reformat
            const date = new Date(dateString.replace(' ', 'T'));
            if (isNaN(date.getTime())) return '—';
            
            // Format as: YYYY-MM-DD HH:MM:SS
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            const hours = String(date.getHours()).padStart(2, '0');
            const minutes = String(date.getMinutes()).padStart(2, '0');
            const seconds = String(date.getSeconds()).padStart(2, '0');
            
            return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
        } catch (e) {
            return dateString;
        }
    },
};
